-- SportSuivi 1.5.0 — إضافات (تُشغَّل بعد ملف 1.4.0). إضافات فقط، لا حذف.
BEGIN;
ALTER TABLE public.test_definitions ADD COLUMN IF NOT EXISTS is_active boolean NOT NULL DEFAULT true;
ALTER TABLE public.chat_messages ADD COLUMN IF NOT EXISTS attachment_path text;
ALTER TABLE public.chat_messages ADD COLUMN IF NOT EXISTS attachment_type text;
INSERT INTO storage.buckets (id,name,public,file_size_limit) VALUES ('chat-files','chat-files',false,10485760) ON CONFLICT (id) DO NOTHING;
DROP POLICY IF EXISTS chat_files_read ON storage.objects;
DROP POLICY IF EXISTS chat_files_insert ON storage.objects;
CREATE POLICY chat_files_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='chat-files' AND public.my_role()='coach');
CREATE POLICY chat_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='chat-files' AND public.my_role()='coach');
-- الاختبارات الأربعة والبارام من ملف Excel (تُضاف فقط إن لم توجد)
INSERT INTO public.test_definitions (institution_id,name,unit,higher_is_better) SELECT (SELECT id FROM public.institutions ORDER BY created_at LIMIT 1),'Navette 20 m (Léger)','palier',true WHERE NOT EXISTS (SELECT 1 FROM public.test_definitions WHERE name ILIKE 'Navette%');
INSERT INTO public.test_definitions (institution_id,name,unit,higher_is_better) SELECT (SELECT id FROM public.institutions ORDER BY created_at LIMIT 1),'Pompes','reps',true WHERE NOT EXISTS (SELECT 1 FROM public.test_definitions WHERE name ILIKE 'Pompes%');
INSERT INTO public.test_definitions (institution_id,name,unit,higher_is_better) SELECT (SELECT id FROM public.institutions ORDER BY created_at LIMIT 1),'Barre fixe (Perfix)',NULL,true WHERE NOT EXISTS (SELECT 1 FROM public.test_definitions WHERE name ILIKE 'Barre%');
INSERT INTO public.test_definitions (institution_id,name,unit,higher_is_better) SELECT (SELECT id FROM public.institutions ORDER BY created_at LIMIT 1),'Abdos','reps',true WHERE NOT EXISTS (SELECT 1 FROM public.test_definitions WHERE name ILIKE 'Abdos%');
